use std::sync::OnceLock;

/// Global print options (simple stand-in for a real numeric formatting backend).
#[derive(Debug, Clone)]
struct PrintOptions {
    precision: u8,
    threshold: u8,
    edgeitems: u8,
    linewidth: u8,
    suppress: bool,
    nanstr: String,
    infstr: String,
    sign: String,
    floatmode: String,
    legacy: String,
}

impl Default for PrintOptions {
    fn default() -> Self {
        Self {
            precision: 8,
            threshold: 100,
            edgeitems: 3,
            linewidth: 75,
            suppress: false,
            nanstr: "nan".to_string(),
            infstr: "inf".to_string(),
            sign: "-".to_string(),
            floatmode: "unique".to_string(),
            legacy: "2.2".to_string(),
        }
    }
}

/// Mutable global state (single-threaded for simplicity).
static mut PRINT_OPTIONS: OnceLock<PrintOptions> = OnceLock::new();

fn with_options_mut<F: FnOnce(&mut PrintOptions)>(f: F) {
    unsafe {
        let ptr: *mut PrintOptions = PRINT_OPTIONS
            .get_or_init(PrintOptions::default)
            as *const PrintOptions as *mut PrintOptions;
        f(&mut *ptr);
    }
}

fn validate_positive_u8(name: &str, v: u8) {
    assert!(v > 0, "{name} must be a strictly positive u8");
}

fn validate_nonempty(name: &str, s: &str) {
    assert!(!s.is_empty(), "{name} must be a non-empty string");
}

fn validate_sign(s: &str) {
    assert!(
        s.len() == 1 && matches!(s.as_bytes()[0], b'-' | b'+' | b' '),
        r#"sign must be exactly one character: "-", "+", or " ""#
    );
}

fn validate_floatmode(s: &str) {
    assert!(
        matches!(s, "fixed" | "unique" | "maxprec" | "maxprec_equal"),
        r#"floatmode must be one of: "fixed", "unique", "maxprec", "maxprec_equal""#
    );
}

fn validate_legacy(s: &str) {
    assert!(
        matches!(s, "1.13" | "1.21" | "1.25" | "2.1" | "2.2"),
        r#"legacy must be one of: "1.13", "1.21", "1.25", "2.1", "2.2""#
    );
}

